solutionCode:
pub fn abrir(caixa: String) -> String {
    format!("[{}] aberta", caixa)
}

testsCode:
use desafio::abrir;

#[test]
fn testa_a_caixa_verde() {
    assert_eq!(abrir(String::from("verde")), "[verde] aberta");
}

#[test]
fn testa_a_caixa_azul() {
    assert_eq!(abrir(String::from("azul")), "[azul] aberta");
}
